component AnimatedGradient {
  ref canvas
  state particles: { x: number, y: number, vx: number, vy: number }[] = []

  mount {
    const ctx = canvas.getContext("2d")
    let animationId: number

    const init = () => {
      particles = Array.from({ length: 50 }, () => ({
        x: Math.random() * canvas.width,
        y: Math.random() * canvas.height,
        vx: (Math.random() - 0.5) * 0.3,
        vy: (Math.random() - 0.5) * 0.3
      }))
    }

    const draw = () => {
      ctx.fillStyle = "rgba(255, 255, 255, 0.01)"
      ctx.fillRect(0, 0, canvas.width, canvas.height)

      const gradient = ctx.createLinearGradient(0, 0, canvas.width, canvas.height)
      gradient.addColorStop(0, "rgba(59, 130, 246, 0.3)")
      gradient.addColorStop(0.5, "rgba(139, 92, 246, 0.3)")
      gradient.addColorStop(1, "rgba(236, 72, 153, 0.3)")

      particles.forEach((p, i) => {
        p.x += p.vx
        p.y += p.vy

        if (p.x < 0 || p.x > canvas.width) p.vx *= -1
        if (p.y < 0 || p.y > canvas.height) p.vy *= -1

        ctx.fillStyle = gradient
        ctx.beginPath()
        ctx.arc(p.x, p.y, 2, 0, Math.PI * 2)
        ctx.fill()
      })

      animationId = requestAnimationFrame(draw)
    }

    init()
    draw()

    cleanup { cancelAnimationFrame(animationId) }
  }

  canvas width=800 height=600 style="position: absolute; inset: 0; width: 100%; height: 100%;" ref=canvas
}

component Counter(target: number) {
  state count = 0

  effect {
    const prefersReducedMotion = window.matchMedia("(prefers-reduced-motion: reduce)").matches
    if (prefersReducedMotion) {
      count = target
      return
    }

    let current = 0
    const duration = 2000
    const start = Date.now()

    const animate = () => {
      const elapsed = Date.now() - start
      const progress = Math.min(elapsed / duration, 1)
      current = Math.floor(progress * target)
      count = current

      if (progress < 1) {
        requestAnimationFrame(animate)
      }
    }

    animate()
  }

  text `${count.toLocaleString()}` bold large
}

