style {
  :root {
    --a-primary: #8b5cf6;
    --a-radius: 12px;
    --a-font: "Inter", sans-serif;
  }

  * {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
  }

  body {
    font-family: var(--a-font);
    background: #0f172a;
    color: #e2e8f0;
    overflow-x: hidden;
  }

  .hero-section {
    position: relative;
    min-height: 100vh;
    padding: 60px 20px;
    z-index: 1;
  }

  .gradient-bg {
    filter: blur(40px);
  }

  .hero-title {
    font-size: 5rem;
    font-weight: 900;
    background: linear-gradient(135deg, #fbbf24, #60a5fa, #34d399);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
    margin-bottom: 20px;
    text-shadow: 0 0 30px rgba(139, 92, 246, 0.3);
  }

  .hero-subtitle {
    max-width: 500px;
    text-align: center;
    color: #cbd5e1;
    margin-bottom: 40px;
  }

  .hero-button {
    padding: 16px 40px;
    font-size: 1.1rem;
    background: linear-gradient(135deg, #8b5cf6, #3b82f6);
    border: none;
    border-radius: 50px;
    color: white;
    font-weight: 600;
    cursor: pointer;
    transition: transform 0.3s ease, box-shadow 0.3s ease;
    box-shadow: 0 10px 30px rgba(139, 92, 246, 0.4);
  }

  .hero-button:hover {
    transform: scale(1.05);
    box-shadow: 0 15px 40px rgba(139, 92, 246, 0.6);
  }

  .hero-button:active {
    transform: scale(0.98);
  }

  @media (prefers-reduced-motion: reduce) {
    .hero-button {
      transition: none;
    }
    .hero-button:hover {
      transform: none;
    }
  }

  .cards-section {
    padding: 80px 20px;
    max-width: 1200px;
    margin: 0 auto;
  }

  .cards-grid {
    flex-wrap: wrap;
  }

  .feature-card {
    flex: 1;
    min-width: 250px;
    max-width: 350px;
    padding: 40px;
    background: rgba(30, 41, 59, 0.8);
    border: 1px solid rgba(148, 163, 184, 0.1);
    border-radius: 16px;
    backdrop-filter: blur(10px);
    text-align: center;
    transition: transform 0.3s ease, border-color 0.3s ease;
  }

  .feature-card:hover {
    transform: translateY(-8px);
    border-color: rgba(139, 92, 246, 0.3);
  }

  @media (prefers-reduced-motion: reduce) {
    .feature-card:hover {
      transform: none;
    }
  }

  .feature-card title {
    margin-bottom: 12px;
  }

  .feature-card text {
    color: #94a3b8;
  }

  .stats-section {
    padding: 80px 20px;
    background: rgba(15, 23, 42, 0.5);
  }

  .counter-container {
    gap: 12px;
  }

  .counter-container {
    font-size: 3.5rem;
    font-weight: 800;
    background: linear-gradient(135deg, #fbbf24, #60a5fa);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
  }

  @media (max-width: 768px) {
    .hero-title {
      font-size: 2.5rem;
    }

    .hero-subtitle {
      font-size: 1rem;
    }

    .cards-grid {
      flex-direction: column;
      align-items: center;
    }

    .feature-card {
      width: 100%;
      max-width: none;
    }
  }
}

