'use client';

import React, { useEffect, useState, useRef } from 'react';

export default function App() {
  const [count, setCount] = useState(0);
  const [isVisible, setIsVisible] = useState(false);
  const countRef = useRef<HTMLDivElement>(null);
  const prefersReducedMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches;

  useEffect(() => {
    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) {
          setIsVisible(true);
        }
      },
      { threshold: 0.5 }
    );

    if (countRef.current) {
      observer.observe(countRef.current);
    }

    return () => {
      if (countRef.current) {
        observer.unobserve(countRef.current);
      }
    };
  }, []);

  useEffect(() => {
    if (!isVisible) return;

    let currentCount = 0;
    const target = 12000;
    const duration = prefersReducedMotion ? 0 : 2000;
    const increment = target / (duration / 16);
    const startTime = Date.now();

    const interval = setInterval(() => {
      const elapsed = Date.now() - startTime;
      const progress = Math.min(elapsed / duration, 1);
      currentCount = Math.floor(progress * target);
      setCount(currentCount);

      if (progress >= 1) {
        clearInterval(interval);
      }
    }, 16);

    return () => clearInterval(interval);
  }, [isVisible, prefersReducedMotion]);

  return (
    <div className="w-full min-h-screen bg-gray-950 text-white overflow-hidden">
      {/* Hero Section */}
      <section className="relative w-full h-screen flex items-center justify-center overflow-hidden">
        {/* Animated Gradient Background */}
        <div
          className={`absolute inset-0 ${
            prefersReducedMotion
              ? 'bg-gradient-to-br from-blue-600 via-purple-600 to-pink-600'
              : 'animate-gradient bg-gradient-to-br from-blue-600 via-purple-600 to-pink-600'
          }`}
          style={
            !prefersReducedMotion
              ? {
                  backgroundSize: '200% 200%',
                  animation: 'gradient-shift 15s ease infinite',
                }
              : {}
          }
        />

        <style>{`
          @keyframes gradient-shift {
            0% {
              background-position: 0% 50%;
            }
            50% {
              background-position: 100% 50%;
            }
            100% {
              background-position: 0% 50%;
            }
          }

          @media (prefers-reduced-motion: reduce) {
            * {
              animation-duration: 0.01ms !important;
              animation-iteration-count: 1 !important;
              transition-duration: 0.01ms !important;
            }
          }
        `}</style>

        {/* Overlay */}
        <div className="absolute inset-0 bg-black/40" />

        {/* Hero Content */}
        <div className="relative z-10 text-center px-4 sm:px-6 lg:px-8">
          <h1 className="text-6xl sm:text-7xl lg:text-8xl font-bold mb-6 text-white drop-shadow-lg">
            Nimbus
          </h1>
          <p className="text-xl sm:text-2xl text-gray-200 mb-10 max-w-2xl mx-auto drop-shadow-md">
            La solución en la nube que transformará tu negocio
          </p>

          {/* CTA Button */}
          <button
            className={`px-8 py-4 bg-white text-blue-600 font-bold text-lg rounded-lg shadow-lg ${
              prefersReducedMotion
                ? ''
                : 'hover:scale-110 hover:shadow-2xl transition-transform duration-300'
            }`}
          >
            Empezar
          </button>
        </div>
      </section>

      {/* Features Section */}
      <section className="py-20 px-4 sm:px-6 lg:px-8 bg-gray-950">
        <div className="max-w-6xl mx-auto">
          <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
            {/* Card 1 - Rápido */}
            <FeatureCard
              title="Rápido"
              description="Rendimiento ultra-rápido con latencia mínima y máxima disponibilidad"
              delay={0}
              prefersReducedMotion={prefersReducedMotion}
            />

            {/* Card 2 - Simple */}
            <FeatureCard
              title="Simple"
              description="Interfaz intuitiva que cualquiera puede usar sin capacitación técnica"
              delay={1}
              prefersReducedMotion={prefersReducedMotion}
            />

            {/* Card 3 - Abierto */}
