              title="Abierto"
              description="API completamente abierta para integrar con tus herramientas favoritas"
              delay={2}
              prefersReducedMotion={prefersReducedMotion}
            />
          </div>
        </div>
      </section>

      {/* Counter Section */}
      <section className="py-20 px-4 sm:px-6 lg:px-8 bg-gradient-to-b from-gray-950 to-gray-900 flex items-center justify-center">
        <div ref={countRef} className="text-center">
          <div className="text-7xl sm:text-8xl font-bold text-transparent bg-gradient-to-r from-blue-400 to-purple-500 bg-clip-text">
            {count.toLocaleString()}+
          </div>
          <p className="text-xl text-gray-300 mt-4">Usuarios confiando en Nimbus</p>
        </div>
      </section>
    </div>
  );
}

interface FeatureCardProps {
  title: string;
  description: string;
  delay: number;
  prefersReducedMotion: boolean;
}

function FeatureCard({
  title,
  description,
  delay,
  prefersReducedMotion,
}: FeatureCardProps) {
  const [isVisible, setIsVisible] = useState(false);
  const cardRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) {
          setIsVisible(true);
        }
      },
      { threshold: 0.5 }
