import { createSignal, createEffect, onMount } from 'solid-js';
import { For } from 'solid-js';
import FeatureCard from './FeatureCard';
import './Features.css';

const features = [
  {
    id: 1,
    title: 'Rápido',
    description: 'Velocidad ultra-rápida en todas tus operaciones'
  },
  {
    id: 2,
    title: 'Simple',
    description: 'Interfaz intuitiva y fácil de usar'
  },
  {
    id: 3,
    title: 'Abierto',
    description: 'Código abierto y transparencia total'
  }
];

export default function Features() {
  const [visibleCards, setVisibleCards] = createSignal([false, false, false]);
  const prefersReducedMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches;

  onMount(() => {
    if (prefersReducedMotion) {
      setVisibleCards([true, true, true]);
      return;
    }

    const timings = [0, 300, 600];
    timings.forEach((delay, index) => {
      setTimeout(() => {
        setVisibleCards(prev => {
          const newVisible = [...prev];
          newVisible[index] = true;
          return newVisible;
        });
      }, delay);
    });
  });

  return (
    <section class="w-full py-24 bg-black px-4">
      <div class="max-w-6xl mx-auto">
        <h2 class="text-4xl md:text-5xl font-bold text-center mb-16">
          Por qué Nimbus
        </h2>

        <div class="grid grid-cols-1 md:grid-cols-3 gap-8">
          <For each={features}>
            {(feature, index) => (
              <FeatureCard
                title={feature.title}
                description={feature.description}
                isVisible={visibleCards()[index()]}
                prefersReducedMotion={prefersReducedMotion}
              />
            )}
          </For>
        </div>
      </div>
    </section>
  );
}

