import { createSignal, createEffect, onMount } from 'solid-js';
import './UserCount.css';

export default function UserCount() {
  const [count, setCount] = createSignal(0);
  const [isVisible, setIsVisible] = createSignal(false);
  const prefersReducedMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches;

  onMount(() => {
    const observer = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting && !isVisible()) {
            setIsVisible(true);

            if (prefersReducedMotion) {
              setCount(12000);
              return;
            }

            const duration = 2000;
            const frameRate = 60;
            const frames = duration / (1000 / frameRate);
            const increment = 12000 / frames;
            let currentCount = 0;
            const startTime = performance.now();

            const animate = (currentTime: number) => {
              const elapsed = currentTime - startTime;
              const progress = Math.min(elapsed / duration, 1);
              currentCount = Math.floor(12000 * progress);
              setCount(currentCount);

              if (progress < 1) {
                requestAnimationFrame(animate);
              } else {
                setCount(12000);
              }
            };

            requestAnimationFrame(animate);
          }
        });
      },
      { threshold: 0.5 }
    );

    const element = document.getElementById('user-count-section');
    if (element) {
      observer.observe(element);
    }

    return () => {
      if (element) {
        observer.unobserve(element);
      }
    };
  });

  const formatNumber = (num: number) => {
    return num.toLocaleString('es-AR');
  };

  return (
    <section
      id="user-count-section"
      class="w-full py-24 bg-gradient-to-b from-black to-gray-900 px-4 flex items-center justify-center"
    >
      <div class="text-center">
        <div class="text-7xl md:text-8xl font-bold mb-4">
          <span class={`${isVisible() ? 'animate-count-in' : ''}`}>
            {formatNumber(count())}
          </span>
          <span class="text-blue-400">+</span>
        </div>
        <p class="text-2xl text-gray-400">usuarios confiando en Nimbus</p>
      </div>
    </section>
  );
}

