import { createSignal } from 'solid-js';

export default function Hero() {
  const [isHovered, setIsHovered] = createSignal(false);

  const prefersReducedMotion = () => {
    if (typeof window === 'undefined') return false;
    return window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  };

  return (
    <div class="relative min-h-screen flex items-center justify-center overflow-hidden">
      {/* Animated gradient background */}
      <div
        class={`absolute inset-0 bg-gradient-to-br from-blue-600 via-purple-600 to-pink-600 ${
          prefersReducedMotion() ? '' : 'animate-gradient-shift'
        }`}
        style={{
          'background-size': '200% 200%',
        }}
      />

      {/* Content */}
      <div class="relative z-10 text-center px-4">
        <h1 class="text-6xl md:text-7xl font-bold text-white mb-6 drop-shadow-lg">
          Nimbus
        </h1>
        <p class="text-xl md:text-2xl text-slate-200 mb-10 drop-shadow-md">
          La plataforma que simplifica tu flujo de trabajo
        </p>

        <button
          onMouseEnter={() => setIsHovered(true)}
          onMouseLeave={() => setIsHovered(false)}
          class={`px-8 py-4 bg-white text-blue-600 font-semibold rounded-lg transition-all duration-300 drop-shadow-lg ${
            prefersReducedMotion()
              ? 'hover:bg-slate-100'
              : isHovered()
              ? 'scale-110 shadow-2xl'
              : 'shadow-lg'
          }`}
        >
          Empezar
        </button>
      </div>
    </div>
  );
}

