import { createSignal, createEffect, For } from 'solid-js';

interface Card {
  id: number;
  title: string;
  description: string;
}

export default function Cards() {
  const cards: Card[] = [
    {
      id: 1,
      title: 'Rápido',
      description: 'Optimizado para rendimiento y velocidad máxima',
    },
    {
      id: 2,
      title: 'Simple',
      description: 'Interfaz intuitiva que cualquiera puede usar',
    },
    {
      id: 3,
      title: 'Abierto',
      description: 'Código abierto y completamente personalizable',
    },
  ];

  const [visibleCards, setVisibleCards] = createSignal<number[]>([]);

  const prefersReducedMotion = () => {
    if (typeof window === 'undefined') return false;
    return window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  };

  createEffect(() => {
    if (prefersReducedMotion()) {
      setVisibleCards(cards.map((c) => c.id));
      return;
    }

    cards.forEach((card, index) => {
      setTimeout(() => {
        setVisibleCards((prev) => [...prev, card.id]);
      }, index * 200);
    });
  });

  return (
    <section class="py-20 px-4 bg-slate-800">
      <div class="max-w-6xl mx-auto">
        <div class="grid grid-cols-1 md:grid-cols-3 gap-8">
          <For each={cards}>
            {(card) => (
              <div
                class={`p-8 bg-slate-700 rounded-lg shadow-lg transition-all duration-500 transform ${
                  visibleCards().includes(card.id)
                    ? 'opacity-100 translate-y-0'
                    : 'opacity-0 translate-y-8'
                }`}
              >
                <h3 class="text-2xl font-bold text-white mb-4">{card.title}</h3>
                <p class="text-slate-300">{card.description}</p>
              </div>
            )}
          </For>
        </div>
      </div>
    </section>
  );
}

