import { createSignal, createEffect, onMount } from 'solid-js';

export default function UserCount() {
  const [count, setCount] = createSignal(0);
  const [isVisible, setIsVisible] = createSignal(false);
  let containerRef: HTMLDivElement | undefined;

  const prefersReducedMotion = () => {
    if (typeof window === 'undefined') return false;
    return window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  };

  onMount(() => {
    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting && !isVisible()) {
          setIsVisible(true);
        }
      },
      { threshold: 0.5 }
    );

    if (containerRef) {
      observer.observe(containerRef);
    }

    return () => {
      if (observer) {
        observer.disconnect();
      }
    };
  });

  createEffect(() => {
    if (!isVisible()) return;

    if (prefersReducedMotion()) {
      setCount(12000);
      return;
    }

    const target = 12000;
    const duration = 2000;
    const startTime = Date.now();

    const animate = () => {
      const elapsed = Date.now() - startTime;
      const progress = Math.min(elapsed / duration, 1);

      const current = Math.floor(progress * target);
      setCount(current);

      if (progress < 1) {
        requestAnimationFrame(animate);
      }
    };

    const frameId = requestAnimationFrame(animate);

    return () => {
      cancelAnimationFrame(frameId);
    };
  });

  return (
    <section ref={containerRef} class="py-20 px-4 bg-slate-900 min-h-screen flex items-center justify-center">
      <div class="max-w-6xl mx-auto text-center">
        <div class="text-5xl md:text-7xl font-bold text-white mb-4">
          {count().toLocaleString('es-ES')}
          <span class="text-blue-400">+</span>
        </div>
        <p class="text-xl text-slate-300">usuarios confiando en Nimbus</p>
      </div>
    </section>
  );
}
